          [['Un **côté de la langue** (ou les deux) contre les molaires du haut', ('AR', 'ض', 48), 'Le ḍâd : le côté de la langue s’appuie contre les dents du fond ; la lettre est **épaisse** et le son **s’étire** le long de la langue.'],
           ['Le **bord avant** de la langue, jusqu’à sa pointe, contre la gencive du haut', ('AR', 'ل', 48), 'Le lâm : la langue touche la gencive, l’air passe par les côtés.'],
           ['La **pointe** de la langue, un peu en dessous du lâm', ('AR', 'ن', 48), 'Le noûn : la pointe touche la gencive ; il porte une **ghounna**.'],
           ['La pointe de la langue, un peu **plus en arrière** que le noûn', ('AR', 'ر', 48), 'Le râ’ : la pointe frappe légèrement le palais, **une seule fois**.']],
