L9 = lesson(e=E, n=9, title='La pointe de la langue et les dents', ar='ط د ت ظ ذ ث ص س ز',
    obj=['connaître les **trois groupes** de lettres de la pointe de la langue ;', 'faire sortir la langue pour ظ ذ ث ;', 'faire siffler ص س ز.'],
    dec=[('g', ['Point de sortie', 'Lettres', 'Comment ?'],
          [['La pointe de la langue contre la **racine des incisives du haut**', ('AR', 'ط  د  ت', 48), 'La langue touche puis se détache. Le ṭâ’ est épais, le dâl et le tâ’ sont fins.'],
           ['La pointe de la langue contre le **bout des incisives du haut**', ('AR', 'ظ  ذ  ث', 48), 'La langue sort un tout petit peu entre les dents. Le ẓâ’ est épais, le dhâl et le thâ’ sont fins.'],
           ['La pointe de la langue **près des incisives du bas**', ('AR', 'ص  س  ز', 48), 'L’air siffle entre la langue et les dents. Le ṣâd est épais, le sîn et le zây sont fins.']],
          [3500, 2000, 4646], ['left', 'center', 'left']),
         ('t', 'Dans chaque groupe, il y a **une lettre épaisse** (ط, ظ, ص) et des lettres fines. C’est la même place de la langue, mais pour la lettre épaisse le fond de la langue monte vers le palais.'),
         ('tip', 'attention', 'Attention', ['Pour ظ ذ ث, la langue doit **se voir** entre les dents. Si elle reste derrière, on entend un z, un d ou un s, et le mot change : ' + W(1, 7, 2) + ' n’est pas « allazîna ».'])],
    ecoute=['Devant un miroir, dites أَثْ, أَذْ, أَظْ : vous devez voir la pointe de la langue entre les dents.', 'Dites أَسْ, أَزْ, أَصْ : la langue reste derrière les dents et l’air siffle. Pour le ṣâd, le fond de la langue monte : le son est plus grave.'],
    ret=['**ط د ت** : pointe de la langue contre la racine des incisives du haut.', '**ظ ذ ث** : pointe de la langue contre le bout des incisives du haut, la langue se voit.', '**ص س ز** : pointe de la langue près des incisives du bas, l’air siffle.'],
    lis=[['أَطْ', 'أَدْ', 'أَتْ', 'أَظْ', 'أَذْ', 'أَثْ', 'أَصْ'], [c[0] for c in FW('طدت', 6)], [c[0] for c in FW('ظذث', 6, sak=False)], [c[0] for c in FW('صسز', 6)]],
    lis_corr=['Ligne 2 : la langue touche la racine des dents. Ligne 3 : la langue se voit entre les dents. Ligne 4 : l’air siffle.'],
    mots=FM('ذث', 3, sak=False) + FM('صز', 3),
    mots_title='MOTS DU CORAN : LES LETTRES DES DENTS', mots_field='Groupe :',
    exos=[dict(title='Je classe', instr='Recopiez chaque lettre dans la colonne de son groupe.', kind='classer',
               data=(['ث', 'ص', 'ط', 'ذ', 'س', 'د', 'ظ', 'ز', 'ت'], ['Racine des dents', 'Bout des dents', 'L’air siffle']),
               corr=['Racine des dents : ط د ت • Bout des dents : ث ذ ظ • L’air siffle : ص س ز.']),
          dict(title='Épaisse ou fine ?', kind='vf', data=['Le ṭâ’ est épais.', 'Le dhâl est épais.', 'Le ṣâd est épais.', 'Le zây est épais.'],
               corr=['1. Vrai. • 2. Faux (fin). • 3. Vrai. • 4. Faux (fin).'])],
    jeu=('Le miroir', 'À deux, avec un petit miroir.', 'L’un lit un mot de « Je lis » en cachant le livre ; l’autre regarde sa bouche dans le miroir et dit si la langue est sortie (ظ ذ ث) ou non. Une bonne réponse rapporte un point ; on change de rôle tous les cinq mots.'),
    bilan=['Je connais les trois groupes de la pointe de la langue.', 'Ma langue se voit pour ظ ذ ث.', 'Je fais siffler ص س ز.'],
    defi=('Lisez ' + V(114, 4) + ' et ' + V(114, 5) + ' en faisant bien siffler le sîn et le ṣâd, sans les confondre.', False),
    cahier=[dict(title='Je complète', kind='bul', data=['Pour ث ذ ظ, la langue se ……… entre les dents.', 'Pour ص س ز, l’air ……… .', 'Dans chaque groupe, une lettre est épaisse : ……… , ……… et ……… .'], corr=['voit • siffle • ط, ظ et ص.']),
            dict(title='Je relie', kind='relier', data=(['ط', 'ث', 'ص'], ['pointe de la langue près des incisives du bas', 'racine des incisives du haut', 'bout des incisives du haut']), corr=['ط → B • ث → C • ص → A.'])],
    mini=[('Pour prononcer ث, ذ et ظ, la langue…', ['se voit un peu entre les dents', 'reste au fond de la bouche', 'touche les lèvres']),
          ('Quelles lettres **sifflent** ?', ['ص س ز', 'ط د ت', 'ق ك ج']),
          ('Quelle lettre est **épaisse** ?', ['le ṭâ’ ط', 'le tâ’ ت', 'le dâl د'])],
    cards=[('ط د ت', 'pointe de la langue, racine des incisives du haut'), ('ظ ذ ث', 'pointe de la langue, bout des incisives du haut'), ('ص س ز', 'pointe de la langue, l’air siffle')])

L10 = lesson(e=E, n=10, title='Les lèvres et le nez', ar='ف و ب م',
    obj=['prononcer **fâ’** avec la lèvre du bas et les dents du haut ;', 'prononcer **bâ’, mîm** et **wâw** avec les deux lèvres ;', 'reconnaître la **ghounna**, le son qui passe par le nez.'],
    dec=[('g', ['Point de sortie', 'Lettres', 'Comment ?'],
          [['L’intérieur de la **lèvre du bas** contre le bout des **incisives du haut**', ('AR', 'ف', 48), 'Le fâ’ : l’air passe entre la lèvre et les dents.'],
           ['Les **deux lèvres**', ('AR', 'ب  م  و', 48), 'Le bâ’ et le mîm : les lèvres se ferment (fortement pour le bâ’, doucement pour le mîm). Le wâw : les lèvres s’arrondissent sans se fermer.'],
           ['La **cavité du nez** (al-khaychoûm)', 'la ghounna', 'Le son nasal du noûn et du mîm : il continue de sortir par le nez.']],
          [3700, 1800, 4646], ['left', 'center', 'left']),
         ('t', 'La **ghounna** est un son agréable qui sort du nez. Elle accompagne toujours le noûn et le mîm, et devient plus longue quand ils portent une chadda, comme dans ' + W(103, 2, 1) + ' et ' + W(102, 4, 1) + ' : on la tient alors **deux temps**. Elle sera très importante à partir de l’étape 4.'),
         ('tip', 'decouvre', 'Le test du nez', ['Pincez doucement votre nez et dites ' + W(103, 2, 1) + ' : le son se bloque. C’est la preuve que la ghounna sort du nez.'])],
    ecoute=['Dites أَفْ : la lèvre du bas touche les dents du haut. Dites أَبْ : les deux lèvres se ferment et se rouvrent avec un petit choc.', 'Dites أَمْ et laissez durer le son : il passe par le nez. Pour le wâw (أَوْ), les lèvres s’arrondissent comme pour souffler une bougie.'],
    ret=['**ف** : lèvre du bas + incisives du haut.', '**ب م و** : les deux lèvres (fermées pour ب et م, arrondies pour و).', 'La **ghounna** sort du nez ; elle dure deux temps avec la chadda (نّ مّ).'],
    lis=[['أَفْ', 'أَبْ', 'أَمْ', 'أَوْ'], [c[0] for c in FW('فب', 6)], [c[0] for c in FW('مو', 6)], [W(103, 2, 1), W(102, 4, 1), W(114, 6, 2), W(114, 1, 4), W(108, 1, 1)]],
    lis_corr=['Ligne 4 : faites durer deux temps la ghounna du noûn et du mîm doublés : إِنَّ (in-na), ثُمَّ (thoum-ma), ٱلْجِنَّةِ, ٱلنَّاسِ, إِنَّآ.'],
    mots=FM('ف', 2) + FM('ب', 2) + [W1(103, 2, 1, pred=P_ANY('ن')), W1(102, 4, 1, pred=P_ANY('م'))],
    mots_title='MOTS DU CORAN : LÈVRES ET GHOUNNA', mots_field='Point de sortie :',
    exos=[dict(title='Je relie', kind='relier', data=(['ف', 'ب', 'و', 'ghounna'], ['lèvres arrondies', 'le nez', 'lèvre du bas et dents du haut', 'lèvres fermées']), corr=['ف → C • ب → D • و → A • ghounna → B.']),
          dict(title='Vrai ou faux ?', kind='vf', data=['Le fâ’ sort des deux lèvres.', 'Pour le wâw, les lèvres se ferment.', 'La ghounna sort du nez.', 'Le noûn doublé a une ghounna de deux temps.'],
               corr=['1. Faux : lèvre du bas et dents du haut. • 2. Faux : elles s’arrondissent. • 3. Vrai. • 4. Vrai.'])],
    jeu=('Le nez pincé', 'En groupe.', 'Chacun pince son nez et lit à voix haute un mot choisi par le meneur. Si le son se bloque, le mot contient une ghounna (noûn ou mîm) ; sinon, il n’en a pas. Les joueurs classent dix mots en deux colonnes : « ghounna » et « sans ghounna ».'),
    bilan=['Je prononce le fâ’ avec la lèvre du bas et les dents du haut.', 'Je distingue bâ’, mîm et wâw.', 'Je fais entendre la ghounna de deux temps du noûn et du mîm doublés.'],
    defi=('Récitez la sourate Al-‘Aṣr en tenant deux temps la ghounna de إِنَّ.', False),
    cahier=[dict(title='Je complète', kind='bul', data=['Le fâ’ sort de la lèvre du ……… et des incisives du ……… .', 'Le bâ’ et le mîm : les lèvres se ……… .', 'La ghounna sort du ……… .'], corr=['bas • haut • ferment • nez.']),
            dict(title='Mon tableau des 17 points de sortie', instr='Sans regarder le livre, écrivez sous chaque zone les lettres qui en sortent : vide de la bouche • gorge • langue • lèvres • nez.', kind='write', data=4,
                 corr=['Vide : lettres de prolongation • Gorge : ء ه ع ح غ خ • Langue : ق ك ج ش ي ض ل ن ر ط د ت ظ ذ ث ص س ز • Lèvres : ف ب م و • Nez : la ghounna.'])],
    mini=[('Le fâ’ sort…', ['de la lèvre du bas et des incisives du haut', 'des deux lèvres fermées', 'du nez']),
          ('Pour prononcer le wâw, les lèvres…', ['s’arrondissent sans se fermer', 'se ferment fortement', 'ne bougent pas']),
          ('La ghounna du noûn doublé (نّ) dure…', ['deux temps', 'un demi-temps', 'six temps'])],
    cards=[('ف', 'lèvre du bas + incisives du haut'), ('ب م و', 'les deux lèvres'), ('ghounna', 'son nasal du noûn et du mîm, sort du nez')])

